ments":[],"widgetType":"text-editor"}],"isInner":true}],"isInner":true}],"isInner":false},{"id":"ljtbl9","elType":"container","settings":{"flex_direction":"column","padding":{"unit":"px","top":"0","right":"20","bottom":"70","left":"20","isLinked":false},"flex_gap":{"unit":"px","size":26,"column":"26","row":"26"}},"elements":[{"id":"ljtblh","elType":"widget","settings":{"title":"Que surveille le suivi des obligations contractuelles ?","align":"center","typography_typography":"custom","typography_font_family":"Roboto Slab","typography_font_weight":"700","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_line_height":{"unit":"em","size":1.3,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"ljtblt","elType":"widget","settings":{"editor":"<p>Chaque famille d’échéances porte son propre risque. Voici ce que l’échéancier de Lumen Juris surveille sur votre portefeuille de contrats, et ce qu’il vous évite.</p>","align":"center","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"400","typography_font_size":{"unit":"px","size":15,"sizes":[]},"text_color":"#39445A","typography_line_height":{"unit":"em","size":1.75,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"ljtbli2","elType":"widget","settings":{"editor":"<p>Le pilotage du portefeuille de contrats ne se joue pas à l’échéance, mais en amont : un préavis de trois mois se dénonce au plus tard trois mois avant le terme, pas la veille. C’est pourquoi les seuils d’alerte de Lumen Juris se calent sur vos préavis réels, extraits des clauses elles-mêmes. Là où un tableur exige une ressaisie manuelle, avec ses erreurs, ses oublis et ses fichiers obsolètes , le référentiel contractuel se met à jour tout seul : chaque contrat signé via la <a href="https://www.lumenjuris.com/signature-electronique-en-ligne/">signature électronique en ligne</a> entre dans l’échéancier sans intervention, avec ses métadonnées, son responsable et sa piste d’audit.</p>","typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"400","typography_font_size":{"unit":"px","size":15,"sizes":[]},"typography_line_height":{"unit":"em","size":1.75,"sizes":[]},"text_color":"#39445A"},"elements":[],"widgetType":"text-editor"},{"id":"ljtblw","elType":"widget","settings":{"html":"<style>
.lj-table-wrap{overflow-x:auto}
.lj-cmp{width:100%;border-collapse:separate;border-spacing:0;background:#fff;
  border:1px solid rgba(27,42,74,.10);border-radius:16px;overflow:hidden;
  font-family:Roboto,sans-serif;font-size:14.5px;color:#39445A;line-height:1.55;min-width:640px}
.lj-cmp th{background:#1B2A4A;color:#fff;font-family:'Roboto Slab',serif;font-weight:600;
  padding:14px 16px;text-align:left;font-size:14px}
.lj-cmp td{padding:13px 16px;border-top:1px solid rgba(27,42,74,.08);vertical-align:top}
.lj-cmp tr td:first-child{font-weight:600;color:#1C1C1C;white-space:nowrap}
</style>
<div class="lj-table-wrap"><table class="lj-cmp">
<thead><tr><th>Échéance surveillée</th><th>Risque si elle passe</th><th>Ce que fait Lumen Juris</th></tr></thead>
<tbody>
<tr><td>Tacite reconduction</td>
<td>Renouvellement subi d’un an aux mêmes conditions, budget engagé sans arbitrage.</td>
<td>Alerte calée sur le préavis de dénonciation réel de la clause, relances jusqu’au traitement.</td></tr>
<tr><td>Information loi Chatel (B2C)</td>
<td>Manquement à l’obligation d’information de l’article L. 215-1 du Code de la consommation.</td>
<td>Alerte Chatel dédiée sur les contrats consommateurs, dans la fenêtre légale d’information.</td></tr>
<tr><td>Jalons et livrables</td>
<td>Pénalités de retard, mise en demeure, dégradation de la relation contractuelle.</td>
<td>Suivi des jalons avec responsable désigné et historique des actions menées.</td></tr>
<tr><td>Révision et indexation de prix</td>
<td>Révision non appliquée : marge rognée ou hausse subie sans négociation.</td>
<td>Rappel à la date d’indexation, avec renvoi à la clause d’échelle mobile concernée.</td></tr>
<tr><td>Obligations récurrentes</td>
<td>Reporting contractuel oublié, assurances non renouvelées, garanties expirées.</td>
<td>Échéancier des obligations périodiques, réparti entre les responsables concernés.</td></tr>
</tbody></table></div>"},"elements":[],"widgetType":"html"},{"id":"ljtblb","elType":"widget","settings":{"text":"Essayez le suivi gratuitement","align":"center","link":{"url":"https://www.lumenjuris.com/contactez-nous/","is_external":"","nofollow":"","custom_attributes":""},"typography_typography":"custom","typography_font_family":"Roboto","typography_font_weight":"700","background_color":"#1B2A4A","button_text_color":"#FFFFFF","border_radius":{"unit":"px","top":"8","right":"8","bottom":"8","left":"8","isLinked":true},"text_padding":{"unit":"px","top":"14","right":"28","bottom":"14","left":"28","isLinked":false},"typography_text_decoration":"none"},"elements":[],"widgetType":"button"}],"isInner":false},{"id":"ljtmo9","elType":"container","settings":{"flex_direction":"column","background_background":"classic","border_radius":{"unit":"px","top":"15","right":"15","bottom":"15","left":"15","isLinked":true},"padding":{"unit":"px","top":"60","right":"40","bottom":"60","left":"40","isLinked":false},"margin":{"unit":"px","top":"0","right":"20","bottom":"70","left":"20","isLinked":false},"flex_gap":{"unit":"px","size":35,"column":"35","row":"35"},"flex_align_items_mobile":"center","margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":true}},"elements":[{"id":"ljtmoh","elType":"widget","settings":{"title":"Un logiciel de suivi contractuel pour chaque équipe","typography_typography":"custom","typography_font_family":"Roboto Slab","typography_font_size":{"unit":"px","size":32,"sizes":[]},"typography_font_weight":"700","align":"center","title_color":"#000000","typography_line_height":{"unit":"em","size":1.3,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"ljtmoi","elType":"widget","settings":{"editor":"<p>Le suivi des contrats concerne autant la direction juridique que les achats, la finance ou les RH : chacun voit ses échéances, ses responsa